    private static int diamondSpellCost(String s){String q=n(s);if(q.equals(n("Detect Magic"))||q.equals(n("Light"))||q.equals(n("Tongues"))||q.equals(n("Detectar Magia"))||q.equals(n("Luz"))||q.equals(n("Idiomas")))return 0;if(q.equals(n("Identify"))||q.equals(n("Identificação")))return 1;if(q.equals(n("Knock"))||q.equals(n("Arrombar")))return 2;if(q.equals(n("True Seeing"))||q.equals(n("Visão da Verdade")))return 3;if(q.equals(n("Legend Lore"))||q.equals(n("Conhecimento Lendário")))return 5;if(q.equals(n("Maze"))||q.equals(n("Labirinto")))return 8;return -1;}
    private static int nightingaleSpellCost(String s){String q=n(s);if(q.equals(n("Detect Evil and Good"))||q.equals(n("Speak with Animals"))||q.equals(n("Detectar o Bem e o Mal"))||q.equals(n("Falar com Animais")))return 0;if(q.equals(n("Calm Emotions"))||q.equals(n("Acalmar Emoções")))return 1;if(q.equals(n("Slow"))||q.equals(n("Lentidão")))return 2;if(q.equals(n("Compulsion"))||q.equals(n("Compulsão")))return 3;if(q.equals(n("Greater Restoration"))||q.equals(n("Restauração Maior")))return 4;if(q.equals(n("Delayed Blast Fireball"))||q.equals(n("Prismatic Spray"))||q.equals(n("Bola de Fogo de Explosão Retardada"))||q.equals(n("Rajada Prismática")))return 6;return -1;}
    private static String ptSpell(String s){String q=n(s);if(q.equals(n("Maze")))return "Labirinto";if(q.equals(n("Teleport")))return "Teleporte";if(q.equals(n("Detect Magic")))return "Detectar Magia";if(q.equals(n("Light")))return "Luz";if(q.equals(n("Identify")))return "Identificação";if(q.equals(n("Knock")))return "Arrombar";if(q.equals(n("Tongues")))return "Idiomas";if(q.equals(n("Legend Lore")))return "Conhecimento Lendário";if(q.equals(n("True Seeing")))return "Visão da Verdade";return s;}
