    private static String necklaceBeast(String c){if(c.contains("Giant Octopus"))return "Polvo Gigante";if(c.contains("Giant Scorpion"))return "Escorpião Gigante";if(c.contains("Hippopotamus"))return "Hipopótamo";if(c.contains("Mammoth"))return "Mamute";if(c.contains("Tyrannosaurus Rex"))return "Tiranossauro Rex";return "forma bestial escolhida pela variante";}
