    private static boolean allowedDamage(String s){String q=n(s);return q.equals("acido")||q.equals("acid")||q.equals("frio")||q.equals("cold")||q.equals("fogo")||q.equals("fire")||q.equals("eletrico")||q.equals("lightning")||q.equals("trovejante")||q.equals("thunder");}
    private static boolean allowedDragon(String s){return allowedDamage(s)||n(s).equals("veneno")||n(s).equals("poison");}
    private static String ptDamage(String s){String q=n(s);if(q.equals("acid")||q.equals("acido"))return "Ácido";if(q.equals("cold")||q.equals("frio"))return "Frio";if(q.equals("fire")||q.equals("fogo"))return "Fogo";if(q.equals("lightning")||q.equals("eletrico"))return "Elétrico";if(q.equals("thunder")||q.equals("trovejante"))return "Trovejante";if(q.equals("poison")||q.equals("veneno"))return "Veneno";return s;}
    private static String canonical(String item){String v=ArcanaUnleashedPtBr.canonical(item);for(String x:PRIMARY)if(sameItem(x,v))return x;for(String x:NECKLACES)if(sameItem(x,v))return x;return "";}
    private static boolean sameItem(String a,String b){return n(a).equals(n(b));}private static boolean sameAction(String normalized,String target){return normalized.equals(n(target));}
    private static JSONArray localized(String[] xs){JSONArray a=new JSONArray();for(String x:xs)a.put(ArcanaUnleashedPtBr.display(x));return a;}
    private static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(Exception e){return new JSONObject();}}
    private static String id(String s){return n(s).replace(' ','_');}
    private static String n(String s){String x=Normalizer.normalize(s==null?"":s.toLowerCase(new Locale("pt","BR")),Normalizer.Form.NFD).replaceAll("\\p{M}+","");return x.replaceAll("[^a-z0-9]+"," ").trim();}
